<?php

namespace App\Http\Requests\Rooms;

use Illuminate\Foundation\Http\FormRequest;

class SendReactionRequest extends FormRequest
{
    /**
     * @return array<string, mixed>
     */
    public function rules(): array
    {
        return [
            // Generated by the client per send; a retry with the same id is delivered only once.
            'client_id' => ['required', 'uuid'],
            'kind' => ['required', 'string', 'in:emoji,message'],
            // An emoji or a message key from the catalog (GET /reactions); checked by RoomReactions.
            'value' => ['required', 'string', 'max:40'],
            // The seat it is for; null (or left out) for everyone at the table.
            'to_seat' => ['nullable', 'integer', 'min:0', 'max:15'],
        ];
    }
}
